var SEQ=1;
function addLink(list, link){
  if(!link||!link.url) return list;
  return list.concat([{id:SEQ++, title:(link.title||link.url).trim(), url:link.url.trim(), tags:(link.tags||'').split(',').map(function(t){return t.trim();}).filter(Boolean)}]);
}
function removeLink(list, id){ return list.filter(function(l){ return l.id!==id; }); }
function search(list, q){
  q=(q||'').trim().toLowerCase(); if(!q) return list;
  return list.filter(function(l){ return (l.title+l.url+l.tags.join(' ')).toLowerCase().indexOf(q)>=0; });
}
var EXPORTS={addLink:addLink,removeLink:removeLink,search:search};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BookmarkForgePure = EXPORTS; }
